﻿:root {
  font-family: 'DM Sans', 'Segoe UI', sans-serif;
  color: #16323d;
  background: #f5f9fa;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --color-page: #f5f9fa;
  --color-surface: #ffffff;
  --color-navy: #102b3a;
  --color-text: #16323d;
  --color-text-muted: #526974;
  --color-on-navy: #f5f9fa;
  --color-on-navy-muted: #b6c8d0;
  --color-primary: #087f83;
  --color-primary-hover: #06676b;
  --color-teal-soft: #dcf3ef;
  --color-teal-bright: #7de0d2;
  --color-blue-bright: #9cc4f5;
  --color-border: #d5e3e8;
  --radius-card: 16px;
  --radius-control: 10px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 112px; }
body { margin: 0; min-width: 320px; font-size: 16px; line-height: 1.65; }
button, input, textarea { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; }
svg, img { display: block; max-width: 100%; }
svg { flex-shrink: 0; }
h1, h2, h3, p, figure { margin: 0; }
h1, h2, h3 { font-family: Manrope, 'Segoe UI', sans-serif; font-weight: 700; letter-spacing: -.04em; }
h2 { font-size: clamp(32px, 3.1vw, 44px); line-height: 1.2; }
h3 { font-size: 23px; line-height: 1.3; }
::selection { color: var(--color-navy); background: var(--color-teal-bright); }
[hidden] { display: none !important; }
:focus-visible { outline: 3px solid var(--color-primary-hover); outline-offset: 5px; }
section[tabindex='-1']:focus, main[tabindex='-1']:focus { outline: none; }
.container { width: min(1200px, calc(100% - 96px)); margin-inline: auto; }
.section-pad { padding-block: 96px; }
.skip-link { position: fixed; top: 12px; left: 12px; z-index: 100; padding: 12px 20px; border-radius: 8px; color: white; background: var(--color-primary-hover); transform: translateY(-160%); }
.skip-link:focus { transform: translateY(0); }

/* Navigation stays available when JavaScript is unavailable. */
.site-header { position: sticky; z-index: 20; top: 0; border-bottom: 1px solid var(--color-border); background: var(--color-surface); }
.header-inner { display: flex; align-items: center; justify-content: space-between; gap: 32px; min-height: 88px; }
.wordmark { display: inline-flex; align-items: center; gap: 12px; flex-shrink: 0; min-height: 44px; }
.brand-symbol { display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; border: 1px solid var(--color-border); border-radius: 12px; color: var(--color-navy); font-family: Manrope, sans-serif; font-size: 23px; font-weight: 700; letter-spacing: -.09em; }
.brand-symbol > span { color: var(--color-primary); }
.brand-name { font-family: Manrope, sans-serif; font-size: 17px; font-weight: 700; line-height: 1.35; letter-spacing: -.03em; }
.brand-name > span { display: block; margin-top: 3px; color: var(--color-text-muted); font-family: 'DM Sans', sans-serif; font-size: 11px; font-weight: 400; letter-spacing: .01em; }
.primary-nav { display: flex; align-items: center; gap: 32px; }
.primary-nav > a { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; font-size: 14px; font-weight: 500; transition: color 160ms, background-color 160ms; }
.primary-nav > a:hover { color: var(--color-primary-hover); }
.primary-nav > .nav-contact { gap: 22px; margin-left: 8px; padding: 10px 19px; border: 1px solid var(--color-border); border-radius: var(--radius-control); color: var(--color-navy); }
.primary-nav > .nav-contact:hover { color: var(--color-primary-hover); background: var(--color-teal-soft); }
.nav-contact > span { font-size: 20px; line-height: 1; }
.menu-toggle { display: none; }

/* Shared type and controls. */
.button { display: inline-flex; align-items: center; justify-content: center; gap: 28px; min-height: 52px; padding: 13px 22px; border: 1px solid transparent; border-radius: var(--radius-control); font-size: 15px; font-weight: 600; line-height: 1.5; transition: background-color 160ms, border-color 160ms; }
.button > span { font-size: 21px; line-height: 1; }
.button-primary { color: white; background: var(--color-primary); }
.button-primary:hover { background: var(--color-primary-hover); }
.text-link { display: inline-flex; align-items: center; gap: 15px; min-height: 48px; padding-block: 9px; font-size: 15px; font-weight: 500; text-decoration: underline; text-decoration-color: #728994; text-underline-offset: 7px; transition: color 160ms; }
.text-link > span { font-size: 21px; line-height: 1; }
.text-link:hover { color: var(--color-primary-hover); }
.eyebrow { display: flex; align-items: center; gap: 10px; color: var(--color-primary-hover); font-size: 12px; font-weight: 600; line-height: 1.5; letter-spacing: .11em; text-transform: uppercase; }
.small-line { flex-shrink: 0; width: 24px; height: 1px; background: currentColor; }
.section-number { margin-right: 3px; color: var(--color-text-muted); font-size: 11px; letter-spacing: .03em; }
.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 48px; margin-bottom: 40px; }
.section-heading h2 { margin-top: 16px; }
.heading-muted { color: var(--color-text-muted); }
.section-lede { max-width: 355px; color: var(--color-text-muted); font-size: 16px; }
.line-icon { display: grid; place-items: center; width: 48px; height: 48px; border: 1px solid var(--color-border); border-radius: 12px; color: var(--color-primary-hover); background: var(--color-page); }
.line-icon svg { width: 25px; height: 25px; }

/* Introduction and an illustrative computer-vision scene, animated by src/scan-figure.js. */
.hero { position: relative; isolation: isolate; color: var(--color-on-navy); background: var(--color-navy); }
.hero-grid { position: absolute; z-index: -1; inset: 0; pointer-events: none; background-image: linear-gradient(#7de0d208 1px, transparent 1px), linear-gradient(90deg, #7de0d208 1px, transparent 1px); background-size: 80px 80px; mask-image: linear-gradient(90deg, transparent 35%, black); }
.hero-layout { display: grid; grid-template-columns: 1.1fr 1fr; align-items: center; gap: 64px; padding-top: 80px; padding-bottom: 72px; }
.hero-copy { min-width: 0; }
.hero-eyebrow { color: var(--color-on-navy-muted); font-size: 11px; letter-spacing: .13em; }
.hero-eyebrow .small-line { background: var(--color-teal-bright); }
.hero-eyebrow > span:not(.small-line) { color: var(--color-teal-bright); }
.hero h1 { margin-top: 26px; font-size: clamp(60px, 5.55vw, 76px); line-height: 1.055; letter-spacing: -.052em; font-weight: 600; }
.hero h1 > span { color: var(--color-teal-bright); }
.hero-intro { max-width: 460px; margin-top: 28px; color: var(--color-on-navy-muted); font-size: 17px; line-height: 1.65; }
.hero-intro strong { color: var(--color-on-navy); font-weight: 500; }
.hero-description { max-width: 440px; margin-top: 12px; color: var(--color-on-navy-muted); font-size: 15px; }
.hero-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 16px 28px; margin-top: 30px; }
.hero .text-link:hover { color: var(--color-teal-bright); }
.hero :focus-visible, .contact-section :focus-visible, .site-footer :focus-visible { outline-color: var(--color-teal-bright); }
.intelligence-figure { width: 100%; max-width: 510px; justify-self: end; border: 1px solid #7de0d22b; border-radius: var(--radius-card); background: #153342; box-shadow: 0 20px 60px #071d2726; }
.figure-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-inline: 24px; padding-block: 21px 19px; border-bottom: 1px solid #7de0d220; color: var(--color-on-navy-muted); font-size: 12px; }
.figure-heading > span:first-child { display: flex; align-items: center; gap: 9px; }
.figure-heading i { width: 6px; height: 6px; border-radius: 50%; background: var(--color-teal-bright); }
.figure-status { padding: 2px 8px; border: 1px solid #7de0d23b; border-radius: 5px; font-size: 11px; letter-spacing: .03em; white-space: nowrap; }
.scan-art { position: relative; margin: 20px 24px 0; }
.scan-art svg { width: 100%; height: auto; }
.scan-label { position: absolute; display: flex; align-items: center; padding: 2px 8px; border-radius: 4px; color: var(--color-navy); font-size: 13px; font-weight: 600; line-height: 1.5; letter-spacing: .02em; white-space: nowrap; transition: opacity 220ms, scale 220ms; }
/* Labels are placed in percentages of the SVG's 480 × 408 viewBox. Each outline label's corner sits on its outline, and the script keeps it there as the parts move. */
.label-instrument { right: 20.5%; bottom: 73.4%; background: var(--color-teal-bright); transform-origin: 100% 100%; }
.label-tissue { left: 24.5%; bottom: 46.8%; background: var(--color-blue-bright); transform-origin: 0 100%; }
.label-probe { background: var(--color-on-navy); transform-origin: 0 100%; }
.label-probe b { margin-left: 6px; font: 500 12px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; letter-spacing: 0; }
.label-track { background: var(--color-teal-bright); transform-origin: 0 100%; }
.label-action { background: var(--color-on-navy); transform-origin: 0 0; }
/* The phase label sits beside the pause button, above the film strip it sums up. */
.label-phase { right: calc(100% * 66 / 480); bottom: calc(100% * 68 / 408); background: var(--color-on-navy); transform-origin: 100% 100%; }
.label-phase i { width: 8px; height: 8px; margin-right: 6px; border-radius: 2px; background: var(--color-teal-bright); }
.scan-label svg { width: 0; height: 10px; transition: width 200ms, margin-left 200ms; }
.scan-label.is-reviewed svg { width: 10px; margin-left: 5px; }
.scan-timecode { fill: var(--color-teal-bright); fill-opacity: .6; font: 500 10px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; letter-spacing: .06em; transition: fill-opacity 200ms; }
.scan-timecode.is-bright { fill-opacity: 1; }
.scan-cursor { position: absolute; top: 0; left: 0; display: none; align-items: flex-start; gap: 1px; margin: -2px 0 0 -2px; opacity: 0; pointer-events: none; }
.scan-cursor svg { width: 16px; height: 21px; filter: drop-shadow(0 2px 3px #04141c80); transform-origin: 2px 2px; transition: scale 120ms; }
.scan-cursor.is-pressing svg { scale: .8; }
.scan-cursor > span { margin-top: 15px; padding: 1px 7px; border-radius: 4px; color: var(--color-navy); background: var(--color-on-navy); font-size: 11px; font-weight: 600; line-height: 1.5; letter-spacing: .02em; white-space: nowrap; }
/* The pause button sits inside the bottom-right corner mark, mirroring the timecode in the bottom-left. */
.scan-toggle { position: absolute; right: calc(100% * 20 / 480); bottom: calc(100% * 68 / 408); display: grid; place-items: center; width: 32px; height: 32px; padding: 0; border: 1px solid #7de0d259; border-radius: 50%; color: var(--color-teal-bright); background: #0a1f29e6; transition: background-color 160ms, border-color 160ms; }
.scan-toggle:hover { border-color: var(--color-teal-bright); background: #153342; }
.scan-toggle svg { width: 12px; height: 12px; }
.scan-toggle .icon-play, .is-paused .scan-toggle .icon-pause { display: none; }
.is-paused .scan-toggle .icon-play { display: block; }
.intelligence-figure figcaption { padding: 0 24px 20px; }
/* Each step is a button under a progress rule that fills during its stage. */
.pipeline-steps { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; margin: 16px 0 0; padding: 0; list-style: none; }
.pipeline-steps button { position: relative; display: block; width: 100%; min-height: 44px; padding: 10px 0 0; border: 0; color: var(--color-on-navy-muted); background: none; font-size: 13px; line-height: 1.35; text-align: left; transition: color 200ms; }
.pipeline-steps button::before, .pipeline-steps button::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 2px; border-radius: 1px; background: #7de0d22e; }
.pipeline-steps button::after { background: var(--color-teal-bright); transform: scaleX(0); transform-origin: left; }
.pipeline-steps .is-done::after { transform: none; }
.pipeline-steps .is-active::after { transform: scaleX(var(--step-progress, 1)); }
.pipeline-steps .is-active, .pipeline-steps button:enabled:hover { color: var(--color-on-navy); }
.pipeline-steps button:disabled { cursor: default; }
.pipeline-steps small { display: block; margin-bottom: 2px; font-size: 11px; letter-spacing: .1em; }
.pipeline-steps :is(.is-active, .is-done) small { color: var(--color-teal-bright); }
.pipeline-steps span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* The descriptions share one grid cell, so the caption keeps the height of the longest. */
.pipeline-details { display: grid; margin-top: 12px; }
.pipeline-detail { grid-area: 1 / 1; visibility: hidden; opacity: 0; color: var(--color-on-navy-muted); font-size: 14px; line-height: 1.55; transition: opacity 200ms, visibility 200ms; }
.pipeline-detail.is-active { visibility: visible; opacity: 1; }
.pipeline-detail strong { color: var(--color-on-navy); font-weight: 600; }
.pipeline-models { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; margin-top: 10px; }
.pipeline-models > span { color: var(--color-teal-bright); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; }
.pipeline-models ul { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none; }
.pipeline-models li { padding: 1px 8px; border: 1px solid #7de0d23b; border-radius: 5px; color: var(--color-on-navy); font-size: 12px; line-height: 1.6; }
/* With the script, labels appear on cue, and the reviewer shows while animated. Without it, only the outline labels show. */
.intelligence-figure:not(.is-scripted) :is(.label-probe, .label-track, .label-action, .label-phase) { display: none; }
.is-scripted .scan-label:not(.is-visible) { opacity: 0; scale: .85; }
.is-animated .scan-cursor { display: flex; }
.is-animated .figure-heading i { animation: scan-live 2s ease-out infinite; }
.is-animated.is-paused .figure-heading i { animation: none; }
@keyframes scan-live { from { box-shadow: 0 0 0 0 #7de0d299; } to { box-shadow: 0 0 0 7px #7de0d200; } }
.figure-note { margin-top: 16px; padding-top: 14px; border-top: 1px solid #7de0d220; color: var(--color-on-navy-muted); font-size: 11px; text-align: center; }
.hero-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 72px; border-top: 1px solid #7de0d223; color: var(--color-on-navy-muted); font-size: 12px; }
.hero-footer > span { letter-spacing: .03em; }
.hero-footer a { display: inline-flex; align-items: center; gap: 18px; min-height: 44px; }
.hero-footer a:hover { color: var(--color-teal-bright); }
.hero-footer a span { color: var(--color-teal-bright); font-size: 19px; }
.credentials-strip { border-bottom: 1px solid var(--color-border); background: var(--color-surface); }
.credentials-inner { display: grid; grid-template-columns: 1.35fr 1px 1fr 1px 1fr; align-items: center; gap: 48px; min-height: 116px; padding-block: 22px; }
.credential-label { display: block; margin-bottom: 2px; color: var(--color-text-muted); font-size: 12px; }
.credentials-inner strong { font-size: 16px; font-weight: 500; }
.credential-divider { align-self: center; height: 38px; background: var(--color-border); }

/* Experience is a dated list; qualifications follow as quiet groups. */
.experience-section { border-block: 1px solid var(--color-border); background: var(--color-surface); }
.experience-list { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--color-border); }
.experience-item { display: grid; grid-template-columns: 240px minmax(0, 1fr); gap: 48px; padding-block: 36px; border-bottom: 1px solid var(--color-border); }
.experience-dates { font-size: 15px; font-weight: 500; }
.experience-location { margin-top: 2px; color: var(--color-text-muted); font-size: 14px; }
.experience-meta .status-label { margin-top: 14px; font-size: 13px; }
.experience-body { max-width: 720px; }
.experience-body h3 { font-size: 23px; }
.experience-org { margin-top: 4px; color: var(--color-primary-hover); font-size: 15px; font-weight: 500; }
.experience-body > p:not(.experience-org), .experience-points { margin-top: 14px; color: var(--color-text-muted); font-size: 16px; }
.experience-points { margin-bottom: 0; padding-left: 20px; }
.experience-points li + li { margin-top: 6px; }
.experience-points li::marker { color: var(--color-primary); }
.topic-tags { display: flex; flex-wrap: wrap; gap: 8px; margin: 20px 0 0; padding: 0; list-style: none; }
.topic-tags li { padding: 4px 10px; border-radius: 6px; color: var(--color-primary-hover); background: var(--color-teal-soft); font-size: 13px; font-weight: 500; }
.qualifications { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; margin-top: 64px; }
.qualification-group { padding-top: 24px; border-top: 1px solid var(--color-border); }
.qualification-group h3 { margin-bottom: 14px; font-size: 19px; }
.qualification-group .topic-tags { margin-top: 0; }
.qualification-list { display: grid; gap: 12px; margin: 0; padding: 0; list-style: none; color: var(--color-text-muted); font-size: 14px; line-height: 1.55; }
.qualification-list strong { display: block; color: var(--color-text); font-weight: 500; }

/* Education is one card per degree. */
.education-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; margin: 0; padding: 0; list-style: none; }
.education-card { padding: 28px; border: 1px solid var(--color-border); border-radius: var(--radius-card); background: var(--color-surface); }
.education-card-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 36px; }
.card-number { color: var(--color-text-muted); font-size: 11px; }
.education-card h3 { font-size: 23px; }
.education-org { margin-top: 4px; color: var(--color-primary-hover); font-size: 15px; font-weight: 500; }
.education-card .status-label { margin-top: 18px; font-size: 13px; }

/* Forthcoming case studies. */
.project-preview { display: grid; grid-template-columns: 1fr 1fr; overflow: hidden; border: 1px solid var(--color-border); border-radius: var(--radius-card); background: var(--color-surface); }
.project-art { position: relative; display: grid; place-items: center; min-height: 448px; padding-block: 44px 64px; overflow: hidden; background: #e0f0ed; background-image: radial-gradient(#087f831c 1px, transparent 1px); background-size: 20px 20px; }
.document-sheet { width: 65%; max-width: 316px; border: 1px solid #b9d3d0; border-radius: 7px; }
.sheet-back { position: absolute; height: calc(100% - 108px); background: #c7e2dd; transform: translate(-18px, -10px) rotate(-9deg); }
.sheet-front { position: relative; padding: 25px 24px; background: #f9fcfb; box-shadow: 0 18px 32px #23453d14; transform: translate(13px, -9px) rotate(5deg); }
.document-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; color: #526974; font-size: 8px; letter-spacing: .13em; }
.document-mark { display: grid; grid-template-columns: 5px 5px; gap: 3px; }
.document-mark i { width: 5px; height: 5px; border: 1px solid var(--color-primary); border-radius: 1px; }
.document-mark i:first-child { background: var(--color-primary); }
.document-heading { margin-top: 20px; color: var(--color-navy); font-family: Manrope, sans-serif; font-size: clamp(19px, 1.8vw, 25px); font-weight: 500; letter-spacing: -.045em; line-height: 1.3; }
.document-rule { height: 1px; margin-top: 16px; background: #cfdfdb; }
.document-diagram { display: flex; align-items: center; margin: 18px 3px; }
.document-diagram > span { width: 27px; height: 27px; flex-shrink: 0; border: 1px solid #6faaa5; border-radius: 7px; background: #e6f3ef; }
.document-diagram > span:nth-of-type(2) { border-color: var(--color-primary); background: var(--color-primary); box-shadow: 0 0 0 5px #dcf3ef; }
.document-diagram > i { height: 1px; flex: 1; margin-inline: 7px; background: #8fbdb4; }
.document-lines { display: grid; gap: 7px; }
.document-lines i { height: 3px; border-radius: 2px; background: #dde9e5; }
.document-lines i:nth-child(2) { width: 88%; }
.document-lines i:nth-child(3) { width: 60%; }
.document-footer { display: block; margin-top: 20px; color: var(--color-text-muted); font-size: 7px; letter-spacing: .11em; }
.art-caption { position: absolute; bottom: 20px; color: var(--color-primary-hover); font-size: 11px; }
.project-preview-copy { align-self: center; padding: 48px; }
.status-label { display: inline-flex; align-items: center; gap: 8px; padding: 5px 11px; border: 1px solid #c9e3dc; border-radius: 6px; color: var(--color-primary-hover); background: #f0f8f5; font-size: 14px; font-weight: 500; }
.status-label > span { width: 5px; height: 5px; border-radius: 50%; background: var(--color-primary-hover); }
.project-preview-copy h3 { margin-block: 22px 18px; font-size: 34px; line-height: 1.2; }
.project-preview-copy > p { color: var(--color-text-muted); font-size: 15px; }
.case-study-topics { display: flex; flex-wrap: wrap; gap: 8px; margin: 22px 0 0; padding: 0; list-style: none; }
.case-study-topics li { padding: 5px 9px; border: 1px solid var(--color-border); border-radius: 5px; color: var(--color-text-muted); font-size: 13px; }
.project-preview-copy > .project-note { margin-top: 24px; padding-top: 20px; border-top: 1px solid var(--color-border); font-size: 12px; }

/* Principles are an ordered sequence, with no hidden content. */
.approach-section { border-top: 1px solid var(--color-border); background: var(--color-surface); }
.approach-heading h2 { margin-top: 16px; }
.approach-heading .section-lede { margin-top: 20px; max-width: none; }
.approach-list { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 28px; margin: 48px 0 0; padding: 0; list-style: none; }
.approach-list li { position: relative; padding-top: 24px; border-top: 1px solid var(--color-border); }
.approach-number { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; margin-bottom: 23px; border: 1px solid #c5e1da; border-radius: 50%; color: var(--color-primary-hover); background: #f0f8f5; font-size: 12px; }
.approach-list h3 { margin-bottom: 13px; font-size: 19px; }
.approach-list p { color: var(--color-text-muted); font-size: 14px; line-height: 1.75; }

/* Personal introduction. */
.about-section { background: var(--color-teal-soft); }
.about-layout { display: grid; grid-template-columns: 1.2fr 1fr; align-items: center; gap: 100px; }
.about-copy h2 { margin-top: 20px; font-size: 46px; }
.teal-period { color: var(--color-primary); }
